INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Роҳнамои пурра барои нигоҳубини дурусти лӯлаи рӯлоии 90-миллиметрӣ бо мақсади дароз кардани ҷисми корӣ ва беҳтар кардани самаранокии системаҳои обёрӣи пайваста барои оҳурхои кӯмакрас.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
