INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','مقارنة شاملة بین نوار تیپ پلاکدار و برندهای ديگری با تمرکز بر کارایی، دوام، و صرفه‌جویی در آب برای سیستم آبیاری قطره‌ای الکترونیکی' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
